package com.campus.lostfound.service; import com.campus.lostfound.entity.*; import com.campus.lostfound.repository.NotificationRepository; import org.springframework.mail.SimpleMailMessage; import org.springframework.mail.javamail.JavaMailSender; import org.springframework.stereotype.Service; @Service public class NotificationService { private final NotificationRepository repo; private final JavaMailSender mail; public NotificationService(NotificationRepository r,JavaMailSender m){repo=r;mail=m;} public void notifyUser(User user,String message){repo.save(new Notification(user,message)); try{SimpleMailMessage msg=new SimpleMailMessage();msg.setTo(user.getEmail());msg.setSubject("Campus Lost & Found Portal");msg.setText(message);mail.send(msg);}catch(Exception ignored){/* In-app notice remains available when SMTP is not configured. */}} }